{
	if (!filter || !RS_IS_FILTER(filter))
	{
		g_warning("Invalid filter pointer provided to rs_filter_draw_graph");
		return;
	}

	GString *str = g_string_new("digraph G {\n");

	rs_filter_graph_helper(str, filter);

	g_string_append(str, "}\n");

	gchar *dot_file = g_build_filename(g_get_tmp_dir(), "filter_graph.dot", NULL);
