	GError *error = NULL;
	if (!g_file_set_contents(dot_file, str->str, -1, &error))
	{
		g_warning("Failed to write DOT file: %s", error ? error->message : "Unknown error");
		if (error)
			g_error_free(error);
		g_string_free(str, TRUE);
		g_free(dot_file);
		g_free(png_file);
		return;
	}

	gchar *dot_cmd = g_strdup_printf("dot -Tpng %s -o %s", dot_file, png_file);
	if (system(dot_cmd) != 0)
	{
		g_warning("Failed to convert DOT to PNG using 'dot' command");
	}
	g_free(dot_cmd);

	gchar *open_cmd = g_strdup_printf("gnome-open %s", png_file);
	if (system(open_cmd) != 0)
	{
		g_warning("Failed to open PNG file using 'gnome-open'");
	}
	g_free(open_cmd);

	g_string_free(str, TRUE);
	g_free(dot_file);
	g_free(png_file);
}
